import os
import time

fn fibonacci(number int) int { if number < 2 { return number }; return fibonacci(number - 1) + fibonacci(number - 2) }
fn fibonacci_iterative(number int) i64 { mut previous := i64(0); mut current := i64(1); for _ in 0 .. number { next := previous + current; previous = current; current = next }; return previous }
fn count_primes(limit int) int { mut prime := []bool{len: limit + 1, init: true}; prime[0] = false; prime[1] = false; for number := 2; number * number <= limit; number++ { if prime[number] { for multiple := number * number; multiple <= limit; multiple += number { prime[multiple] = false } } }; mut count := 0; for value in prime { if value { count++ } }; return count }
fn main() { fibonacci_input := os.args[1].int(); prime_limit := os.args[2].int(); numeric_iterations := os.args[3].int(); mut start := time.now(); fibonacci_result := fibonacci(fibonacci_input); ft := time.now().unix_micro() - start.unix_micro(); start = time.now(); prime_result := count_primes(prime_limit); pt := time.now().unix_micro() - start.unix_micro(); start = time.now(); mut numeric_result := i64(0); for _ in 0 .. numeric_iterations { numeric_result += fibonacci_iterative(fibonacci_input) }; nt := time.now().unix_micro() - start.unix_micro(); if numeric_result < 0 { panic('benchmark result validation failed') }; println('${f64(ft) / 1000000.0},${f64(pt) / 1000000.0},${f64(nt) / 1000000.0},${fibonacci_result},${prime_result},${numeric_result}') }
